1	@import "tailwindcss";
2	@import "tw-animate-css";
3	@import "shadcn/tailwind.css";
4	
5	/* Exclude docs directory — contains literal Tailwind class strings in markdown that generate invalid CSS */
6	@source not "../docs/**";
7	
8	@custom-variant dark (&:is(.dark *));
9	
10	@theme inline {
11	  /* ──────────────────────────────────────────────────────────
12	     INKOS BRAND SWATCHES — Brand Book v1.0 (LOCKED)
13	     Bone · Onyx · Stone · Rust — no additions, no substitutes
14	  ────────────────────────────────────────────────────────── */
15	  --color-bone: #F7F7F5;
16	  --color-onyx: #0F0F0F;
17	  --color-stone: #787774;
18	  --color-rust: #B23A2B;
19	
20	  --font-sans: var(--font-sans), 'Inter', -apple-system, sans-serif;
21	  --font-serif: var(--font-serif), 'Instrument Serif', Georgia, serif;
22	  --font-mono: var(--font-mono), 'JetBrains Mono', monospace;
23	
24	  /* ──────────────────────────────────────────────────────────
25	     SEMANTIC PALETTE — derived from brand swatches
26	     Rule: never pure #FFF or #000. Bone/Onyx only.
27	  ────────────────────────────────────────────────────────── */
28	
29	  /* Bone — 60% usage. Page canvas + sidebar bg. */
30	  --color-background: #F7F7F5;
31	
32	  /* Onyx — 20% usage. Primary text + CTAs. */
33	  --color-foreground: #0F0F0F;
34	
35	  /* Card surface — pure white on Bone, so cards "float" */
36	  --color-card: #FFFFFF;
37	  --color-card-foreground: #0F0F0F;
38	
39	  --color-popover: #FFFFFF;
40	  --color-popover-foreground: #0F0F0F;
41	
42	  /* Primary = Onyx (NOT Rust). Primary CTAs are black. */
43	  --color-primary: #0F0F0F;
44	  --color-primary-foreground: #F7F7F5;
45	
46	  /* Secondary — muted Bone tint */
47	  --color-secondary: oklch(96% 0.003 60);
48	  --color-secondary-foreground: #0F0F0F;
49	
50	  /* Muted — Stone-tinted backgrounds */
51	  --color-muted: oklch(95% 0.003 60);
52	  --color-muted-foreground: #787774;
53	
54	  /* Accent — Rust at 12% opacity for active nav states */
55	  --color-accent: rgba(178, 58, 43, 0.08);
56	  --color-accent-foreground: #B23A2B;
57	
58	  /* Destructive = Rust. Reserved for LIVE pill, active nav, destructive only. */
59	  --color-destructive: #B23A2B;
60	  --color-destructive-foreground: #F7F7F5;
61	
62	  /* ──────────────────────────────────────────────────────────
63	     SEMANTIC STATUS TOKENS
64	  ────────────────────────────────────────────────────────── */
65	  --color-success:            oklch(58% 0.18 145);
66	  --color-success-bg:         oklch(94% 0.05 145);
67	  --color-success-foreground: oklch(26% 0.12 145);
68	  --color-warning:            oklch(70% 0.16 72);
69	  --color-warning-bg:         oklch(94% 0.07 72);
70	  --color-warning-foreground: oklch(36% 0.15 72);
71	
72	  /* Borders — Stone-tinted, warm hue, tuned to be visible on bone canvas */
73	  --color-border: oklch(91% 0.005 85);
74	  --color-input: oklch(91% 0.005 85);
75	  --color-ring: #0F0F0F;
76	
77	  /* ──────────────────────────────────────────────────────────
78	     SHADOWS — custom (never use Tailwind default shadow-sm/md)
79	  ────────────────────────────────────────────────────────── */
80	
81	  /* Soft border shadow for cards on white — bumped alpha so cards read on bone bg */
82	  --shadow-soft: 0 1px 2px 0 oklch(20% 0.02 85 / 0.08), 0 1px 3px 0 oklch(20% 0.02 85 / 0.05);
83	
84	  /* Standard card elevation — visible on off-white page */
85	  --shadow-card: 0 1px 3px 0 oklch(20% 0.02 85 / 0.10), 0 2px 4px -1px oklch(20% 0.02 85 / 0.06);
86	
87	  /* Hover elevation */
88	  --shadow-card-hover: 0 6px 16px -4px oklch(20% 0.02 85 / 0.14), 0 3px 8px -2px oklch(20% 0.02 85 / 0.09);
89	
90	  /* Medium depth for drawers, modals */
91	  --shadow-soft-md: 0 4px 16px -4px oklch(13% 0.015 85 / 0.10), 0 2px 8px -2px oklch(13% 0.015 85 / 0.07);
92	
93	  /* Floating elements — command palette, toasts, tooltips */
94	  --shadow-lift: 0 8px 24px -4px oklch(13% 0.015 85 / 0.14),
95	                 0 4px 10px -2px oklch(13% 0.015 85 / 0.08);
96	
97	  /* Full-screen overlays — modal backdrop shadow on dialog */
98	  --shadow-overlay: 0 24px 64px -12px oklch(13% 0.015 85 / 0.22),
99	                    0 8px 24px -4px oklch(13% 0.015 85 / 0.12);
100	
101	  /* ──────────────────────────────────────────────────────────
102	     RADIUS
103	  ────────────────────────────────────────────────────────── */
104	  --radius: 0.5rem;
105	  --radius-sm: 0.25rem;
106	  --radius-md: 0.5rem;
107	  --radius-lg: 0.75rem;
108	  --radius-xl: 1rem;
109	  --radius-2xl: 1.5rem;   /* 24px — large modals, full-bleed cards */
110	  --radius-full: 9999px;  /* pill buttons, avatar chips, progress bars */
111	
112	  /* ──────────────────────────────────────────────────────────
113	     TYPOGRAPHY
114	  ────────────────────────────────────────────────────────── */
115	  --font-sans: var(--font-geist-sans), system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
116	  --font-mono: var(--font-geist-mono), "Fira Code", "Cascadia Code", ui-monospace, monospace;
117	
118	  /* ──────────────────────────────────────────────────────────
119	     TYPOGRAPHY SCALE — semantic names
120	  ────────────────────────────────────────────────────────── */
121	  --text-display-size:    2.25rem;  /* 36px */
122	  --text-display-height:  2.5rem;   /* 40px */
123	  --text-display-weight:  700;
124	  --text-display-track:   -0.02em;
125	
126	  --text-h1-size:    1.75rem;       /* 28px */
127	  --text-h1-height:  2rem;          /* 32px */
128	  --text-h1-weight:  700;
129	  --text-h1-track:   -0.015em;
130	
131	  --text-h2-size:    1.25rem;       /* 20px */
132	  --text-h2-height:  1.75rem;       /* 28px */
133	  --text-h2-weight:  600;
134	  --text-h2-track:   -0.01em;
135	
136	  --text-h3-size:    1rem;          /* 16px */
137	  --text-h3-height:  1.5rem;        /* 24px */
138	  --text-h3-weight:  600;
139	  --text-h3-track:   -0.005em;
140	
141	  --text-body-size:    0.875rem;    /* 14px */
142	  --text-body-height:  1.25rem;     /* 20px */
143	  --text-body-weight:  400;
144	  --text-body-track:   0em;
145	
146	  --text-body-sm-size:    0.8125rem; /* 13px */
147	  --text-body-sm-height:  1.125rem;  /* 18px */
148	  --text-body-sm-weight:  400;
149	  --text-body-sm-track:   0em;
150	
151	  --text-caption-size:    0.75rem;  /* 12px */
152	  --text-caption-height:  1rem;     /* 16px */
153	  --text-caption-weight:  400;
154	  --text-caption-track:   0em;
155	
156	  --text-micro-size:    0.625rem;   /* 10px */
157	  --text-micro-height:  0.875rem;   /* 14px */
158	  --text-micro-weight:  500;
159	  --text-micro-track:   0.06em;     /* uppercase tracking */
160	
161	  /* ──────────────────────────────────────────────────────────
162	     SPACING CONSTANTS — semantic aliases
163	  ────────────────────────────────────────────────────────── */
164	  --spacing-page-x:      1.5rem;   /* px-6 — desktop page horizontal padding */
165	  --spacing-page-x-sm:   1rem;     /* px-4 — mobile page horizontal padding */
166	  --spacing-page-y:      1.5rem;   /* py-6 — vertical section gap */
167	  --spacing-card-pad:    1.5rem;   /* p-6  — card internal padding */
168	  --spacing-card-gap:    1rem;     /* gap-4 — gap between cards in a grid */
169	  --spacing-section-gap: 1.5rem;   /* space-y-6 — between page sections */
170	  --spacing-field-gap:   1rem;     /* space-y-4 — between form fields */
171	
172	  /* ──────────────────────────────────────────────────────────
173	     ICON SIZE SCALE — reference constants (see lib/design-tokens.ts)
174	  ────────────────────────────────────────────────────────── */
175	  --icon-xs:  0.75rem;   /* 12px */
176	  --icon-sm:  0.875rem;  /* 14px */
177	  --icon-md:  1rem;      /* 16px */
178	  --icon-lg:  1.25rem;   /* 20px */
179	  --icon-xl:  1.5rem;    /* 24px */
180	  --icon-2xl: 2rem;      /* 32px */
181	
182	  /* ──────────────────────────────────────────────────────────
183	     SIDEBAR TOKENS (shadcn sidebar primitives)
184	  ────────────────────────────────────────────────────────── */
185	  /* L0 — recessed chrome: ~2% deeper than L1 bone canvas so the sidebar reads
186	     as "behind" the content area. Premium SaaS elevation ladder. */
187	  --sidebar: oklch(95.5% 0.004 85);
188	  --sidebar-background: oklch(95.5% 0.004 85);
189	  --sidebar-foreground: #0F0F0F;
190	  --sidebar-primary: #0F0F0F;
191	  --sidebar-primary-foreground: #F7F7F5;
192	  --sidebar-accent: rgba(178, 58, 43, 0.10);
193	  --sidebar-accent-foreground: #B23A2B;
194	  --sidebar-border: oklch(91% 0.005 85);
195	  --sidebar-ring: #0F0F0F;
196	  /* S24 — bumped 15→16rem. 240px was tight for "Flash & Portfolio" + STUDIO
197	     pill + icon and made the chrome feel undernourished. 256px matches the
198	     industry sweet spot (Linear, Shopify admin, Vercel) and gives nav rows
199	     measurable breathing room on either side of the label. */
200	  --sidebar-width: 16rem;

