200	  --sidebar-width: 16rem;
201	  --sidebar-width-mobile: 19rem;
202	  --sidebar-width-icon: 3.5rem;
203	
204	  /* shadcn token aliases */
205	  --color-sidebar: var(--sidebar);
206	  --color-sidebar-foreground: var(--sidebar-foreground);
207	  --color-sidebar-primary: var(--sidebar-primary);
208	  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
209	  --color-sidebar-accent: var(--sidebar-accent);
210	  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
211	  --color-sidebar-border: var(--sidebar-border);
212	  --color-sidebar-ring: var(--sidebar-ring);
213	
214	  /* ──────────────────────────────────────────────────────────
215	     PAGE LAYOUT — light mode
216	     Brand Book v1.0 — Bone/Stone/Onyx. Hue 85 = warm stone neutral.
217	     (was hue 264 = cool blue — fixed to remove subtle blue tint.)
218	  ────────────────────────────────────────────────────────── */
219	  --color-page-bg: oklch(97.5% 0.003 85);
220	  --color-header-bg: oklch(100% 0 0);
221	  --color-surface-1: oklch(100% 0 0);
222	  --color-surface-2: oklch(97.5% 0.003 85);
223	
224	  /* ──────────────────────────────────────────────────────────
225	     FLASH INVENTORY STATUS TOKENS (Sprint 13)
226	     Derived from Bone/Onyx only — no new hues.
227	  ────────────────────────────────────────────────────────── */
228	  --color-status-available:    var(--color-bone);           /* bg */
229	  --color-status-available-fg: var(--color-onyx);           /* text */
230	  --color-status-available-bd: var(--color-onyx);           /* border */
231	  --color-status-reserved:     oklch(20% 0 0 / 0.60);       /* bg — Onyx 60% */
232	  --color-status-reserved-fg:  var(--color-bone);           /* text */
233	  --color-status-sold:         var(--color-onyx);           /* bg */
234	  --color-status-sold-fg:      var(--color-bone);           /* text */
235	
236	  /* ──────────────────────────────────────────────────────────
237	     CHIP TOKENS — used across public pages + flash cards
238	  ────────────────────────────────────────────────────────── */
239	  --color-chip-bg:         oklch(95% 0.003 85);
240	  --color-chip-foreground: var(--color-onyx);
241	  --color-chip-border:     oklch(88% 0.005 85);
242	
243	  /* ──────────────────────────────────────────────────────────
244	     STATUS BADGES — tattoo booking lifecycle
245	  ────────────────────────────────────────────────────────── */
246	  --color-status-pending: oklch(70% 0.16 72);
247	  --color-status-confirmed: oklch(62% 0.24 292);
248	  --color-status-in-progress: oklch(60% 0.2 200);
249	  --color-status-completed: oklch(58% 0.18 145);

